select * from jsonb_to_recordset($review$[{"row": 7, "id": "worldbank-catalog:fm-lbl-bmny-zg", "title": "Fastest broad-money growth rate", "comment": "Remove", "source": "https://data.worldbank.org/indicator/FM.LBL.BMNY.ZG", "year": "2024", "action": "retire", "reason": "Explicit owner removal"}, {"row": 8, "id": "gdpGrowth", "title": "Fastest economic growth rate", "comment": "It would be helpful to specify the year \"gdp growth 2024-2025\".", "source": "https://data.worldbank.org/indicator/NY.GDP.MKTP.KD.ZG", "year": "2025", "action": "clarify", "new_title": "Fastest GDP growth in {year}", "new_description": "Annual growth in economic output after adjusting for inflation, compared with the previous year"}, {"row": 9, "id": "worldbank-catalog:fm-ast-domo-zg-m3", "title": "Fastest growth rate in domestic credit relative to broad money", "comment": "X If there is a good explanation of what broad money is, maybe these could be restored.", "source": "https://data.worldbank.org/indicator/FM.AST.DOMO.ZG.M3", "year": "2024", "action": "retire", "reason": "Retire pending a simpler, useful broad money concept; no automatic restoration"}, {"row": 10, "id": "worldbank-catalog:fm-ast-cgov-zg-m3", "title": "Fastest growth rate in government credit relative to broad money", "comment": "Remove", "source": "https://data.worldbank.org/indicator/FM.AST.CGOV.ZG.M3", "year": "2024", "action": "retire", "reason": "Explicit owner removal"}, {"row": 11, "id": "worldbank-catalog:fm-ast-prvt-zg-m3", "title": "Fastest growth rate in private credit relative to broad money", "comment": "Remove", "source": "https://data.worldbank.org/indicator/FM.AST.PRVT.ZG.M3", "year": "2024", "action": "retire", "reason": "Explicit owner removal"}, {"row": 14, "id": "natural-earth:landlocked-fewest-neighbors", "title": "Fewest land-border neighbors among landlocked countries", "comment": "Fun!", "source": "https://www.naturalearthdata.com/", "year": "2022", "action": "retain", "reason": "Positive owner feedback; keep category"}, {"row": 15, "id": "sports:fifa-world-cup-first-appearance", "title": "First men's FIFA World Cup appearance", "comment": "\"First\" doesn’t specify if you want the oldest or most recent.", "source": "https://www.fifa.com/tournaments/mens/worldcup", "year": "2026", "action": "clarify", "new_title": "Earliest men's FIFA World Cup debut", "new_description": "First World Cup appearance among countries that have participated; earlier years rank higher"}, {"row": 16, "id": "pew-religion:other-religions-share", "title": "Highest % following religions outside the five major groups", "comment": "Interesting, but are we supposed to know what the five major groups are?", "source": "https://www.pewresearch.org/religion/feature/religious-composition-by-country-2010-2020/", "year": "2020", "action": "clarify", "new_title": "Highest % following other religions", "new_description": "Religions other than Christianity, Islam, Hinduism, Buddhism or Judaism; excludes people with no religion"}, {"row": 18, "id": "worldbank-catalog:fb-ast-nper-zs", "title": "Highest % of bank loans that are nonperforming", "comment": "\"nonperforming is how a bank would refer to these. Maybe say \"unpaid\" or \"in default\"", "source": "https://data.worldbank.org/indicator/FB.AST.NPER.ZS", "year": "2024", "action": "clarify", "new_title": "Highest % of bank loans overdue or unlikely to be repaid", "new_description": "Loans overdue by at least 90 days or otherwise unlikely to be repaid in full, as a share of all bank loans"}, {"row": 24, "id": "worldbank-catalog:eg-cft-accs-zs", "title": "Highest % of people using clean cooking fuels", "comment": "Huh \"clean\" is pretty subjective.", "source": "https://data.worldbank.org/indicator/EG.CFT.ACCS.ZS", "year": "2023", "action": "clarify", "new_title": "Highest % using cooking fuels meeting WHO clean air criteria", "new_description": "People mainly cooking with electricity, gas, biogas, solar or alcohol fuels, classified using WHO household air pollution guidelines"}, {"row": 34, "id": "worldbank-catalog:eg-cft-accs-ru-zs", "title": "Highest % of rural residents using clean cooking fuels", "comment": "REMOVE", "source": "https://data.worldbank.org/indicator/EG.CFT.ACCS.RU.ZS", "year": "2023", "action": "retire", "reason": "Explicit owner removal"}, {"row": 36, "id": "unsdg:urban-slum-share", "title": "Highest % of urban residents living in slums", "comment": "Is there a defition of slum?", "source": "https://unstats.un.org/sdgs/dataportal/database", "year": "2024", "action": "clarify", "new_title": null, "new_description": "Urban households lacking safe water, sanitation, enough living space, durable housing or secure tenure, under the UN definition"}, {"row": 37, "id": "worldbank-catalog:eg-cft-accs-ur-zs", "title": "Highest % of urban residents using clean cooking fuels", "comment": "Remove", "source": "https://data.worldbank.org/indicator/EG.CFT.ACCS.UR.ZS", "year": "2023", "action": "retire", "reason": "Explicit owner removal"}, {"row": 42, "id": "worldbank-catalog:fb-bnk-capa-zs", "title": "Highest bank capital as % of assets", "comment": "Remove", "source": "https://data.worldbank.org/indicator/FB.BNK.CAPA.ZS", "year": "2024", "action": "retire", "reason": "Explicit owner removal"}, {"row": 43, "id": "worldbank-catalog:fd-ast-prvt-gd-zs", "title": "Highest bank credit to the private sector as % of GDP", "comment": "Remove", "source": "https://data.worldbank.org/indicator/FD.AST.PRVT.GD.ZS", "year": "2024", "action": "retire", "reason": "Explicit owner removal"}, {"row": 44, "id": "worldbank-catalog:fd-res-liqu-as-zs", "title": "Highest bank liquid reserves as % of assets", "comment": "Remove", "source": "https://data.worldbank.org/indicator/FD.RES.LIQU.AS.ZS", "year": "2024", "action": "retire", "reason": "Explicit owner removal"}, {"row": 46, "id": "worldbank-catalog:fm-lbl-bmny-gd-zs", "title": "Highest broad money as % of GDP", "comment": "Remove", "source": "https://data.worldbank.org/ind