", "year": "2023", "action": "retire", "reason": "Explicit owner removal"}, {"row": 102, "id": "worldbank-catalog:en-ghg-all-pc-ce-ar5", "title": "Highest greenhouse-gas emissions per person", "comment": "No dash", "source": "https://data.worldbank.org/indicator/EN.GHG.ALL.PC.CE.AR5", "year": "2024", "action": "remove_unnecessary_hyphens", "reason": "Apply catalog-wide wording cleanup"}, {"row": 106, "id": "worldbank-catalog:gc-tax-ypkg-zs", "title": "Highest income and profit taxes as % of all taxes", "comment": "Remove", "source": "https://data.worldbank.org/indicator/GC.TAX.YPKG.ZS", "year": "2023", "action": "retire", "reason": "Explicit owner removal"}, {"row": 107, "id": "worldbank-catalog:gc-tax-ypkg-rv-zs", "title": "Highest income and profit taxes as % of government revenue", "comment": "Remove", "source": "https://data.worldbank.org/indicator/GC.TAX.YPKG.RV.ZS", "year": "2023", "action": "retire", "reason": "Explicit owner removal"}, {"row": 110, "id": "undp-hdr:education-inequality", "title": "Highest inequality in schooling (%)", "comment": "Define this - unclear metric", "source": "https://hdr.undp.org/data-center", "year": "2023", "action": "clarify", "new_title": null, "new_description": "Uneven distribution of years of schooling among adults, measured by the Atkinson inequality index; higher percentages mean greater inequality"}, {"row": 111, "id": "worldbank-catalog:fp-cpi-totl-zg", "title": "Highest inflation rate", "comment": "A time frame would be good 2024-25? 2015-25?", "source": "https://data.worldbank.org/indicator/FP.CPI.TOTL.ZG", "year": "2025", "action": "clarify", "new_title": "Highest inflation in {year}", "new_description": "Annual percentage increase in consumer prices compared with the previous year"}, {"row": 112, "id": "worldbank-catalog:bx-klt-dinv-wd-gd-zs", "title": "Highest inward foreign investment as % of GDP", "comment": "Remove inward - is that necessary?", "source": "https://data.worldbank.org/indicator/BX.KLT.DINV.WD.GD.ZS", "year": "2024", "action": "clarify", "new_title": "Highest foreign investment received as % of GDP", "new_description": "Direct investment received from abroad, after subtracting withdrawals, as a percentage of economic output"}, {"row": 118, "id": "worldbank-catalog:gc-xpn-othr-zs", "title": "Highest miscellaneous government spending as % of expenses", "comment": "Remove", "source": "https://data.worldbank.org/indicator/GC.XPN.OTHR.ZS", "year": "2022", "action": "retire", "reason": "Explicit owner removal"}, {"row": 119, "id": "worldbank-catalog:gc-tax-othr-rv-zs", "title": "Highest miscellaneous taxes as % of government revenue", "comment": "Remove", "source": "https://data.worldbank.org/indicator/GC.TAX.OTHR.RV.ZS", "year": "2022", "action": "retire", "reason": "Explicit owner removal"}, {"row": 121, "id": "worldbank-catalog:fm-ast-prvt-gd-zs", "title": "Highest monetary-sector private credit as % of GDP", "comment": "Remove", "source": "https://data.worldbank.org/indicator/FM.AST.PRVT.GD.ZS", "year": "2024", "action": "retire", "reason": "Explicit owner removal"}, {"row": 122, "id": "unwpp:highest-natural-change-rate", "title": "Highest natural population increase rate", "comment": "How is this defferent from fertility or general growth rate?", "source": "https://population.un.org/wpp/", "year": "2023", "action": "clarify", "new_title": "Fastest population growth from births minus deaths", "new_description": "Annual births minus deaths per 1,000 residents; excludes immigration and emigration"}, {"row": 123, "id": "worldbank-catalog:fs-ast-cgov-gd-zs", "title": "Highest net claims on government as % of GDP", "comment": "What sort of claims?", "source": "https://data.worldbank.org/indicator/FS.AST.CGOV.GD.ZS", "year": "2024", "action": "clarify", "new_title": "Highest net government borrowing from banks as % of GDP", "new_description": "Banks’ loans and other claims on central government minus government deposits, as a percentage of economic output"}, {"row": 125, "id": "unwpp:highest-net-migration-rate", "title": "Highest net migration rate", "comment": "Does this mean both in and out? Or within the country?", "source": "https://population.un.org/wpp/", "year": "2023", "action": "clarify", "new_title": "Highest net immigration per 1,000 residents", "new_description": "People moving into the country minus people moving out during the year, per 1,000 residents; excludes moves within the country"}, {"row": 126, "id": "worldbank-catalog:ic-bus-ndns-zs", "title": "Highest new-business density", "comment": "Remove unless could be changed to most new businesses, or just most business growth", "source": "https://data.worldbank.org/indicator/IC.BUS.NDNS.ZS", "year": "2024", "action": "retire", "reason": "Per 1,000 adults is not a business total or growth rate; retain the existing total registrations category instead"}, {"row": 127, "id": "worldbank-catalog:bm-klt-dinv-wd-gd-zs", "title": "Highest outward foreign investment as % of GDP", "comment": "Remove", "source": "https://data.worldbank.org/indicator/BM.KLT.DINV.WD.GD.ZS", "year": "2024", "action": "retire", "reason": "Explicit owner removal"}, {"row": 128, "id": "koppen-geiger:continental-share", "title": "Highest percentage of land with a continental climate", "comment": "I've never heard of a continental climate", "source": "https://doi.org/10.1038/s41597-023-02549-6", "year": "2020", "action": "clarify", "new_title": null, "new_description": "Cold winters: coldest month averages 0°C or below and warmest month above 10°C; excludes arid land"}, {"row": 129, "id": "koppen-geiger:desert-share", "title": "Highest percentage of land with a desert climate", "comment": "Is there an actual definition for this?", "source": "https://doi.org/10.1038/s41597-023-02549-6", "year": "2020", "action": "clarify", "new_title": null, "new_description": "Very dry land receiving less than half the rainfall threshold for arid climates; the threshold depends on temperature and seasonal rainfall"}, {"row": 130, "id": "koppen-geiger:mediterranean-share", "title": "Highest percentage of land with a Mediterranean climate", "comment": "Is there an actual definition for this?", "source": "https://doi.org/10.1038/s41597-023-02549-6", "year": "2020", "action": "clarify", "new_title": null, "new_description": "A type of temperate climate with dry summers and wetter winters; not limited to countries around the Mediterranean Sea"}, {"row": 131, "id": "koppen-geiger:polar-share", "title": "Highest percentage of land with a polar climate", "comment": "Is there an actual definition for this?", "source": "https://doi.org/10.1038/s41597-023-02549-6", "year": "2020", "action": "clarify", "new_title": null, "new_description": "Land where even the warmest month averages 10°C or below; includes tundra and ice cap climates, excluding arid land"}, {"row": 132, "id": "koppen-geiger:steppe-share", "title": "Highest percentage of land with a steppe climate", "comment": "I have no idea what steppe climate means", "source": "https://doi.org/10.1038/s41597-023-02549-6", "year": "2020", "action": "clarify", "new_title": "Highest percentage of land with a semiarid steppe climate", "new_description": "Dry land with more rain than deserts but below the arid climate rainfall threshold, which varies with temperature and seasonal rainfall"}, {"row": 133, "id": "koppen-geiger:temperate-share", "title": "Highest percentage of land with a temperate climate", "comment": "Is there an actual definition for this? How do mediterrean and temperate climates differ?", "source": "https://doi.org/10.1038/s41597-023-02549-6", "year": "2020", "action": "clarify", "new_title": null, "new_description": "Coldest month averages above 0°C but below 18°C and warmest month above 10°C; excludes arid land and includes Mediterranean climates"}, {"row": 134, "id": "koppen-geiger:tropical-monsoon-share", "title": "Highest percentage of land with a tropical monsoon climate", "comment": "Is there an actual definition for this?", "source": "https://doi.org/10.1038/s41597-023-02549-6", "year": "2020", "action": "clarify", "new_title": null, "new_description": "Every month averages at least 18°C, with a short dry season; classified using both the driest month and annual rainfall"}, {"row": 135, "id": "koppen-geiger:tropical-rainforest-share", "title": "Highest percentage of land with a tropical rainforest climate", "comment": "Is there an actual definition for this?", "source": "https://doi.org/10.1038/s41597-023-02549-6", "year": "2020", "action": "clarify", "new_title": null, "new_description": "Every month averages at least 18°C and receives at least 60 mm of rain"}, {"row": 136, "id": "koppen-geiger:tundra-share", "title": "Highest percentage of land with a tundra climate", "comment": "Is there an actual definition for this?", "source": "https://doi.org/10.1038/s41597-023-02549-6", "year": "2020", "action": "clarify", "new_title": null, "new_description": "Warmest month averages above 0°C but no more than 10°C; excludes arid land and climates cold enough for an ice cap"}, {"row": 137, "id": "koppen-geiger:arid-share", "title": "Highest percentage of land with an arid climate", "comment": "How is arid =/= desert?", "source": "https://doi.org/10.1038/s41597-023-02549-6", "year": "2020", "action": "clarify", "new_title": null, "new_description": "An umbrella group covering both very dry deserts and less dry steppes, classified using temperature and seasonal rainfall"}, {"row": 140, "id": "worldbank-catalog:dt-tds-dppf-xp-zs", "title": "Highest public and IMF debt payments as % of exports", "comment": "Remove", "source": "https://data.worldbank.org/indicator/DT.TDS.DPPF.XP.ZS", "year": "2023", "action": "retire", "reason": "Explicit owner removal"}, {"row": 141, "id": "worldbank-catalog:dt-tds-dppg-xp-zs", "title": "Highest public foreign-debt payments as % of export income", "comment": "Remove", "source": "https://data.worldbank.org/indicator/DT.TDS.DPPG.XP.ZS", "year": "2023", "act