do $$ begin
 if (select count(*) from owner_review_input)<>90 or (select count(*) from owner_review_input i join public.stat_categories c on c.id=i.id)<>90 then
 raise exception 'Owner workbook does not match 90 existing categories'; end if;
end $$;
-- Keep all decisions in the existing durable contract layer used by importer refreshes.
insert into public.category_review_contracts_v16_3_4 as existing(category_id,review_patch,presentation_patch)
select i.id,
 case when i.action='retire' then jsonb_build_object('status','rejected','notes','Owner workbook 2026-09-08: '||coalesce(i.reason,i.comment))
 else '{}'::jsonb end,
 case when i.action='clarify' then jsonb_build_object(
 'metadata',jsonb_strip_nulls(jsonb_build_object('ownerReviewTitle',i.new_title,'ownerReviewDescription',i.new_description,'ownerReviewDate','2026-09-08','boardDescription',i.new_description)))
 else '{}'::jsonb end
from owner_review_input i join public.category_runtime_review_v16_2 v on v.id=i.id
where i.action in ('retire','clarify')
on conflict(category_id) do update set
 review_patch=existing.review_patch||excluded.review_patch,
 presentation_patch=existing.presentation_patch||excluded.presentation_patch||jsonb_build_object('metadata',coalesce(existing.presentation_patch->'metadata','{}'::jsonb)||coalesce(excluded.presentation_patch->'metadata','{}'::jsonb)),
 revision=existing.revision+1,updated_at=now();
update public.category_review_state s set status='rejected',notes='Owner workbook 2026-09-08: '||coalesce(i.reason,i.comment),updated_at=now()
from owner_review_input i where i.id=s.category_id and i.action='retire';
update public.stat_categories c set enabled=false,eligible_daily=false,review_status='rejected',curation_status='excluded',content_review_status='excluded',player_quality_status='blocked'
from owner_review_input i where i.id=c.id and i.action='retire';
-- Fires the copy-contract trigger before recalculating catalog assessments.
update public.stat_categories c set title=c.title from owner_review_input i where c.id=i.id and i.action='clarify';
-- Replace recovery witnesses with freshly verified boards using only retained categories.
