update public.category_recovery_evidence_v16_3_4 e set
 proofs=(select jsonb_agg(p) from owner_fresh_proofs f where f.p->>'category_id'=e.category_id),
 snapshot_fingerprint=public.category_recovery_fingerprint_v16_3_4(e.category_id),
 dependency_fingerprints=(select jsonb_object_agg(d.id,public.category_recovery_fingerprint_v16_3_4(d.id)) from (select distinct jsonb_array_elements_text(p->'witness'->'categories') id from owner_fresh_proofs f where f.p->>'category_id'=e.category_id) d),
 assessed_at=now()
where exists(select 1 from owner_fresh_proofs f where f.p->>'category_id'=e.category_id);
select public.refresh_v16_2_runtime_catalog();
do $$ begin
 if exists(select 1 from owner_review_before b join public.stat_categories c on c.id=b.id where b.enabled and not c.enabled and not exists(select 1 from owner_review_input i where i.id=c.id and i.action='retire')) then
 raise exception 'Unrequested category disabled by owner review'; end if;
 if exists(select 1 from public.stat_categories c join owner_review_input i on i.id=c.id where i.action='retire' and (c.enabled or c.eligible_daily)) then
 raise exception 'An owner retirement was re-enabled during refresh'; end if;
end $$;
commit;
